    importOnDoubleClick->setChecked(KdenliveSettings::mediaDoubleClickImport());
    connect(importOnDoubleClick, &QAction::triggered, this, [](bool enabled) { KdenliveSettings::setMediaDoubleClickImport(enabled); });

