    autoPlay->setCheckable(true);
    autoPlay->setChecked(KdenliveSettings::mediaBrowserAutoPlay());
    connect(autoPlay, &QAction::triggered, this, [](bool enable) { KdenliveSettings::setMediaBrowserAutoPlay(enable); });

    // Create View
