                        barZone.anchors.left = undefined
                        barZone.anchors.right = barZone.parent.right
                    }
                    barZone.rightSide = !barZone.rightSide
                    effecttoolbar.fadeBar()
                }
            }
        }
    }

    Rectangle {
        id: autoKeyframeIndicator
        anchors {
            top: parent.top
            horizontalCenter: parent.horizontalCenter
            topMargin: 8
        }
        width: 14
        height: 14
        radius: 7
        color: "#ff3b30"
        border.color: "#ffffff"
        border.width: 1.5
        visible: K.KdenliveSettings.autoKeyframe

